    section3Body: 'መወዳእታ ወርሓዊ ደም ቀስ ብቀስ ናብ ሃይማኖታዊ ንጽህና ኩነታት ምምላስ የመልክት። ብኣካላዊ ኣገባብ፡ እዚ ምቁራጽ ደም እዩ፡ ዝተፈላለዩ ኣለማዊ ልምድታት ብቁሩብ ዝተፈላለዩ ንኡስ ትርጉማት ክገልጽዎ ዝኽእሉ መለክዒ።',
    visual1Title: 'ፍይዚዮሎጂያዊ ሂደት',
    visual1Text: 'ደረጃታት ዑደት ምርዳእ ወርሓዊ ደም ብሓቂ ዝውዳእሉ እዋን ዝበለጸ ንምፍላጥ ይሕግዘኪ።',
    section3Body2: 'እዚ መለክዒ ምስ ተራእየ፡ ጉስል (ዓቢ ውዱእ) ናብ ሃይማኖታዊ ንጽህና ንምምላስን ዝተቋረጹ ኣምልኾታት ንምቕጻልን የኽእል።',
    section4Body: 'ጉስል ንምልእቲ ኣካል ብኣእላ ንጽህና ምሕጻብ ዘጠቓልል ዓቢ ሃይማኖታዊ ውዱእ እዩ። ምቕናይ ይውድእ ሰላት ብንቡር ክቕጽል የኽእል፡ ኣብ ወርሓዊ ደም ዝተሓለፉ ሰላታት ምክፋል ዘድልዩ ብዘይ።',
    visual2Title: 'ናይ ምንጻህ ስርዓት',
