    section5Body: 'ወርሓዊ ደም ብሓቂ ዝወደአሉ እዋን ጥርጣረ ምስምዓይ ልሙድ እዩ፡ ብፍላይ ደም ድንገት ከይቆመ ቀስ ብቀስ ምስ ዝንከይ።',
