    metaValidated: 'Okuqukethwe okubuyekeziwe',
    intro: 'Ukuqonda ubuhlobo phakathi komjikelezo nesimo sokuhlanzeka kwenkolo, ukusondela kulesi sikhathi ngokucacile kakhulu.',
