    section1Body: 'Na lisolo ya Islam, bopɛtɛ ya losambo (tahara) elimboli lolenge oyo esengeli mpo na kosala misala mosusu ya losambo, lokola mabondeli. Elimboli bopɛtɛ ya mokolo na mokolo te, kasi lolenge ya mpenza eyebani na fiqh, oyo ebongwanaka engebene na ba etape ya cycle ya mwasi.',
    section2Body: 'Na ntango ya sanza, mwasi alongwaka na misala mosusu ya losambo, mingi mingi mabondeli mpe kokila kolia ya Ramadan, oyo ekoki kozongisama sima. Kolongwa oyo eyebani lokola lisalisi, lokola etumbu te.',
    checkList1Title: 'Oyo ekoba kozala possible na ntango ya sanza',
