    section3Body: 'Suka ya sanza elakisi kozonga moke moke na lolenge ya bopɛtɛ ya losambo. Na nzoto, yango ekokani na kotika ya makila, elembo oyo mikanda ndenge ndenge ya ba scholar ekoki kolimbola na bokeseni moke.',
    visual1Title: 'Mosala ya nzoto',
    visual1Text: 'Kososola ba etape ya cycle esalisi yo koyeba malamu ntango sanza esili mpenza.',
    section3Body2: 'Sima ya komona elembo oyo, ghusl (kosukola monene) epesaka nzela ya kozonga na bopɛtɛ ya losambo mpe kozongela misala ya losambo oyo etikamaki.',
    section4Body: 'Ghusl ezali kosukola monene ya losambo oyo esengi kosukola nzoto mobimba na mokano ya kopɛtola nzoto. Elakisi suka ya kolongwa mpe epesi nzela ete mabondeli ezonga na ndenge ya ndenge, kozanga esengeli ya kozongisa mabondeli oyo etikamaki na ntango ya sanza.',
    visual2Title: 'Mosala ya kopɛtola',
    visual2Text: 'Ndenge ya mpenza ghusl esalemaka ekoki kokeseni moke engebene na kanda ya fiqh olandaka.',
    tip1Title: 'Eloko ya koyeba',
    tip1Text: 'Soki oyebi te banzela ya mpenza oyo olandaka na kanda na yo, moto oyo omekaka motema na ye to scholar oyo ayebi akoki kolimbola yo yango polele.',
    section5Body: 'Ezali ya mbala mingi koyoka ntembe na ntina ya ntango sanza esili mpenza, mingi mingi ntango makila ekitaka malembe na esika ya kotika mbalakaka.',
    checkList2Title: 'Bilembo mosusu ya ntina',
