    noteTitle: 'Ki lura',
    noteText: 'Wasu bayanai (kamar karanta Alƙur’ani kai tsaye ko shiga masallaci) na iya bambanta bisa mazhabar fiqhu; ya fi kyau a koma ga ra’ayin da kike bi yawanci ko ga ƙwararren malami kan waɗannan takamaiman lokuta.',
    section3Body: 'Ƙarshen haila yana alamar komawa a hankali ga yanayin tsarki na ibada. A zahiri, wannan yana dacewa da tsayawar zubar jini, wata alama da al’adun malamai daban-daban za su iya ayyana ta da ɗan bambanci.',
    visual1Title: 'Tsarin jiki',
    visual1Text: 'Fahimtar matakan zagaye yana taimaka miki ki fi gano lokacin da haila ta ƙare da gaske.',
