    section4Body: 'Ghusl babban wanka ne na ibada wanda ya ƙunshi wanke jiki gaba ɗaya da niyyar tsarkakewa. Yana alamar ƙarshen hutu kuma yana ba da damar sallah ta ci gaba kamar yadda aka saba, ba tare da bukatar rama sallolin da aka rasa lokacin haila ba.',
