    noteTitle: 'ልብ በይ',
    noteText: 'አንዳንድ ዝርዝሮች (እንደ ቁርአንን በቀጥታ ማንበብ ወይም መስጊድ መግባት) በፊቅህ ትምህርት ቤት መሠረት ሊለያዩ ይችላሉ፤ ለእነዚህ ልዩ ሁኔታዎች በተለምዶ የምትከተይውን ራይ ወይም ብቁ ሊቅን መመልከት ይሻላል።',
    section3Body: 'የወር አበባ ማብቃት ቀስ በቀስ ወደ አምልኮ ንጽሕና ሁኔታ መመለስን ያመለክታል። በአካል ደረጃ ይህ ከደም መፍሰስ መቆም ጋር ይዛመዳል፣ የተለያዩ የሊቃውንት ወጎች በትንሹ በተለየ ትንታኔ ሊወስኑት የሚችሉት ምልክት።',
    visual1Title: 'የፊዚዮሎጂ ሂደት',
    visual1Text: 'የዑደቱን ደረጃዎች መረዳት የወር አበባ በእውነት የሚያበቃበትን ጊዜ በተሻለ እንድትለዪ ይረዳሻል።',
    section3Body2: 'ይህ ምልክት ከታየ በኋላ፣ ጉስል (ትልቅ ውዱእ) ወደ አምልኮ ንጽሕና ለመመለስ እና የተቋረጡ የአምልኮ ተግባራትን ለመቀጠል ያስችላል።',
    section4Body: 'ጉስል ራስን ለማጽዳት በማሰብ መላ ሰውነትን መታጠብን የሚያካትት ትልቅ የአምልኮ ውዱእ ነው። የፈቃዱን ማብቂያ ያመለክታል እና በወር አበባ ጊዜ የተረሱ ሶላቶችን መካስ ሳያስፈልግ ሶላት በተለምዶ እንዲቀጥል ያስችላል።',
    visual2Title: 'የማጽዳት ሥርዓት',
    visual2Text: 'ጉስል የሚደረግበት ትክክለኛ መንገድ በሚከተለው የፊቅህ ትምህርት ቤት መሠረት በትንሹ ሊለያይ ይችላል።',
