    section5Body: 'የወር አበባ በእውነት መቼ እንዳበቃ መጠራጠር የተለመደ ነው፣ በተለይ ደም መፍሰሱ በድንገት ከመቆም ይልቅ ቀስ በቀስ ሲቀንስ።',
