    section1Body: 'Στην ισλαμική παράδοση, η τελετουργική καθαρότητα (ταχάρα) αναφέρεται στην κατάσταση που απαιτείται για την εκτέλεση ορισμένων πράξεων λατρείας, όπως η προσευχή. Δεν αναφέρεται στην καθαριότητα με την καθημερινή έννοια, αλλά σε μια συγκεκριμένη κατάσταση που αναγνωρίζεται από το φικχ και αλλάζει ανάλογα με τα στάδια του γυναικείου κύκλου.',
    section2Body: 'Κατά την έμμηνο ρύση, η γυναίκα απαλλάσσεται από ορισμένες πράξεις λατρείας, ιδίως την προσευχή και τη νηστεία του Ραμαζανιού, η οποία μπορεί να αναπληρωθεί αργότερα. Αυτή η απαλλαγή αναγνωρίζεται ως διευκόλυνση, όχι ως τιμωρία.',
