    section3Body: 'માસિકનો અંત ધીમે ધીમે પાકીની સ્થિતિમાં પાછા ફરવાનું દર્શાવે છે. શારીરિક રીતે, આ રક્તસ્રાવ બંધ થવાને અનુરૂપ છે, એક એવો સંકેત જેને વિવિધ વિદ્વાન પરંપરાઓ થોડા અલગ ભેદ સાથે વ્યાખ્યાયિત કરી શકે છે.',
    visual1Title: 'એક શારીરિક પ્રક્રિયા',
    visual1Text: 'ચક્રના તબક્કાઓ સમજવાથી તમને માસિક ખરેખર ક્યારે પૂરું થાય છે તે ક્ષણ વધુ સારી રીતે ઓળખવામાં મદદ મળે છે.',
    section3Body2: 'આ સંકેત જોવા મળે પછી, ગુસ્લ (મોટું સ્નાન) દ્વારા પાકીમાં પાછા ફરી શકાય છે અને સ્થગિત થયેલી ઇબાદત ફરી શરૂ કરી શકાય છે.',
    section4Body: 'ગુસ્લ એક મોટું ધાર્મિક સ્નાન છે, જેમાં પોતાને પાક કરવાની નિયત સાથે આખા શરીરને ધોવામાં આવે છે. તે મુક્તિનો અંત દર્શાવે છે અને નમાઝ સામાન્ય રીતે ફરી શરૂ કરવાની મંજૂરી આપે છે, અને માસિક દરમિયાન ચૂકી ગયેલી નમાઝની કઝા કરવી જરૂરી નથી.',
