    section5Body: 'માસિક ખરેખર ક્યારે પૂરું થયું તે વિશે શંકા થવી સામાન્ય છે, ખાસ કરીને જ્યારે રક્તસ્રાવ અચાનક બંધ થવાને બદલે ધીમે ધીમે ઘટે.',
