    alert2Title: 'મહત્વની માહિતી',
    alert2Text: 'લાંબા કે અનિયમિત રક્તસ્રાવ, અથવા સતત શંકાના કિસ્સાઓમાં, આ પરિસ્થિતિઓ લાયક વિદ્વાન સાથે ચર્ચવા યોગ્ય છે, જે તમારી વ્યક્તિગત પરિસ્થિતિ મુજબ તમને માર્ગદર્શન આપી શકે. આ સામગ્રી માહિતી માટેની જ રહે છે અને વ્યક્તિગત ધાર્મિક માર્ગદર્શનનું સ્થાન લેતી નથી.',
