    noteTitle: 'ਕਿਰਪਾ ਕਰਕੇ ਧਿਆਨ ਦਿਓ',
    noteText: 'ਕੁਝ ਵੇਰਵੇ (ਜਿਵੇਂ ਕੁਰਆਨ ਨੂੰ ਸਿੱਧਾ ਪੜ੍ਹਨਾ ਜਾਂ ਮਸਜਿਦ ਵਿੱਚ ਜਾਣਾ) ਫ਼ਿਕਹ ਦੇ ਮਸਲਕ ਅਨੁਸਾਰ ਵੱਖਰੇ ਹੋ ਸਕਦੇ ਹਨ; ਇਨ੍ਹਾਂ ਖ਼ਾਸ ਸੂਰਤਾਂ ਲਈ ਬਿਹਤਰ ਹੈ ਕਿ ਤੁਸੀਂ ਜਿਸ ਰਾਇ ਦੀ ਆਮ ਤੌਰ ਤੇ ਪੈਰਵੀ ਕਰਦੇ ਹੋ ਉਸ ਨੂੰ ਜਾਂ ਕਿਸੇ ਯੋਗ ਵਿਦਵਾਨ ਨੂੰ ਵੇਖੋ।',
    section3Body: 'ਮਾਹਵਾਰੀ ਦਾ ਅੰਤ ਪਾਕੀ ਦੀ ਹਾਲਤ ਵਿੱਚ ਹੌਲੀ-ਹੌਲੀ ਵਾਪਸੀ ਦਾ ਸੰਕੇਤ ਹੈ। ਸਰੀਰਕ ਤੌਰ ਤੇ ਇਹ ਖ਼ੂਨ ਵਹਿਣ ਦੇ ਬੰਦ ਹੋਣ ਨਾਲ ਮੇਲ ਖਾਂਦਾ ਹੈ, ਇੱਕ ਅਜਿਹਾ ਸੰਕੇਤ ਜਿਸ ਨੂੰ ਵਿਦਵਾਨਾਂ ਦੀਆਂ ਵੱਖ-ਵੱਖ ਪਰੰਪਰਾਵਾਂ ਥੋੜ੍ਹੇ ਵੱਖਰੇ ਬਾਰੀਕ ਫ਼ਰਕਾਂ ਨਾਲ ਪਰਿਭਾਸ਼ਿਤ ਕਰ ਸਕਦੀਆਂ ਹਨ।',
    visual1Title: 'ਇੱਕ ਸਰੀਰਕ ਪ੍ਰਕਿਰਿਆ',
    visual1Text: 'ਚੱਕਰ ਦੇ ਪੜਾਵਾਂ ਨੂੰ ਸਮਝਣ ਨਾਲ ਤੁਸੀਂ ਉਸ ਪਲ ਨੂੰ ਬਿਹਤਰ ਪਛਾਣ ਸਕਦੇ ਹੋ ਜਦੋਂ ਮਾਹਵਾਰੀ ਸੱਚਮੁੱਚ ਖ਼ਤਮ ਹੁੰਦੀ ਹੈ।',
    section3Body2: 'ਜਦੋਂ ਇਹ ਸੰਕੇਤ ਵੇਖ ਲਿਆ ਜਾਵੇ, ਤਾਂ ਗ਼ੁਸਲ (ਵੱਡਾ ਇਸ਼ਨਾਨ) ਨਾਲ ਪਾਕੀ ਵਿੱਚ ਵਾਪਸ ਆਇਆ ਜਾ ਸਕਦਾ ਹੈ ਅਤੇ ਰੁਕੀਆਂ ਹੋਈਆਂ ਇਬਾਦਤਾਂ ਮੁੜ ਸ਼ੁਰੂ ਕੀਤੀਆਂ ਜਾ ਸਕਦੀਆਂ ਹਨ।',
    section4Body: 'ਗ਼ੁਸਲ ਇੱਕ ਵੱਡਾ ਧਾਰਮਿਕ ਇਸ਼ਨਾਨ ਹੈ ਜਿਸ ਵਿੱਚ ਪਾਕ ਹੋਣ ਦੀ ਨੀਅਤ ਨਾਲ ਪੂਰੇ ਸਰੀਰ ਨੂੰ ਧੋਇਆ ਜਾਂਦਾ ਹੈ। ਇਹ ਛੋਟ ਦੇ ਅੰਤ ਨੂੰ ਦਰਸਾਉਂਦਾ ਹੈ ਅਤੇ ਨਮਾਜ਼ ਨੂੰ ਆਮ ਵਾਂਗ ਮੁੜ ਸ਼ੁਰੂ ਕਰਨ ਦੀ ਆਗਿਆ ਦਿੰਦਾ ਹੈ, ਅਤੇ ਮਾਹਵਾਰੀ ਦੌਰਾਨ ਛੁੱਟੀਆਂ ਨਮਾਜ਼ਾਂ ਨੂੰ ਕਜ਼ਾ ਕਰਨ ਦੀ ਲੋੜ ਨਹੀਂ ਹੁੰਦੀ।',
    visual2Title: 'ਪਾਕ ਹੋਣ ਦੀ ਇੱਕ ਰਸਮ',
    visual2Text: 'ਗ਼ੁਸਲ ਕਰਨ ਦਾ ਸਹੀ ਤਰੀਕਾ ਤੁਹਾਡੇ ਮਸਲਕ ਅਨੁਸਾਰ ਥੋੜ੍ਹਾ ਵੱਖਰਾ ਹੋ ਸਕਦਾ ਹੈ।',
